print("=== โปรแกรมคำนวณการใช้สีทาบ้านภายนอก ==="); weight, long, height = int(input("กรุณากรอก ความกว้าง ของบ้าน (เมตร): ")), int(input("กรุณากรอก ความยาว ของบ้าน (เมตร): ")), int(input("กรุณากรอก ความสูง ของบ้าน (เมตร): ")); print("\n=== สรุปผลการคำนวณ ==="); area = weight * height * 2 + long * height * 2; color_total = area / 2.5; color_num = round(color_total / 4); print(f"พื้นที่ผนั้งภายนอกทั้งหมด: {area:.2f} ตารางเมตร"); print(f"ปริมาณสีที่ต้องใช้รวม: {color_total:.2f} ลิตร"); print(f"จำนวนสีกระป๋องที่ต้องซื้อ: {color_num} กระป๋อง"); print(f"จำนวนเงินค่าสีทั้งหมด: {color_num * 200:,} บาท")